from pathlib import Path
import ast,hashlib,json,shutil
f=json.loads(Path('rag/eval/baselines/answer_evidence_v2/manifest.json').read_text())
for name in f['files']:
    if name.startswith('rag/service/') or name=='rag/retrieval/search_chunks.py':assert hashlib.sha256(Path(name).read_bytes()).hexdigest()==f['files'][name],name
old=ast.parse(Path('rag/service/retrieval_server.py').read_text());new=ast.parse(Path('/tmp/travel-plan-stage-20261013/service/retrieval_server.py').read_text())
for name in ('ask_api','search_api'):
    fn=lambda tree:next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name==name)
    assert ast.dump(fn(old))==ast.dump(fn(new)),name
backup=Path('deploy/backups/planning-2026-10-13');backup.mkdir(parents=True,exist_ok=False)
shutil.copyfile('rag/service/retrieval_server.py',backup/'retrieval_server.py')
(backup/'manifest.json').write_text(json.dumps({'unit_tests_passed':80,'no_secrets_archived':True,'previous_planning_flag':'0','ask_and_search_handlers_unchanged':True}))
for name in ('plan_service.py','retrieval_server.py'):shutil.copyfile(Path('/tmp/travel-plan-stage-20261013/service')/name,Path('rag/service')/name)
shutil.copyfile('/tmp/travel-plan-stage-20261013/eval/test_plan_service.py','rag/eval/test_plan_service.py')
p=Path('.env');lines=[line for line in p.read_text().splitlines() if not line.startswith('RAG_PLANNING_ENABLED=')];lines.append('RAG_PLANNING_ENABLED=1');p.write_text('\n'.join(lines)+'\n')
print('Planning enabled on independent /plan; existing /ask and /search unchanged')
